// 内置的「鱼八股 / AI 腔」黑名单。fishrules.js 可以在这个基础上再加。
// 每条：[正则, 说明]。说明会原样显示给用户和 agent。
'use strict'

const BLACKLIST = [
  [/这条我认/, '鱼八股原句「这条我认」'],
  [/我(先)?记下了/, '鱼八股原句「我记下了」'],
  [/这是本鱼最喜欢的/, '鱼八股原句「这是本鱼最喜欢的一句话」'],
  [/收到主人/, '女仆腔「收到主人」'],
  // 盲测里测出来的：人设带的动作括号，一眼就露馅
  [/[（(][^）)]{0,10}(尾巴|鳍|耳朵|爪子|蹭蹭|摇摇|啪嗒|眨眼|歪头|叉腰)[^）)]{0,8}[）)]/, '角色扮演的动作括号（「（尾巴摇摇）」这种），评论区没人这么写'],
  [/这本身就是/, 'AI 腔「这本身就是……」'],
  [/说到(了)?根上/, 'AI 腔「说到根上了」'],
  [/不是.{1,14}[，,]\s*(而)?是/, '「不是 A，是 B」式对仗，太工整'],
  [/作为一(个|名)\s*AI/i, '「作为一个 AI」'],
  [/总(的)?(来|而言之)说?/, '总结腔'],
  [/值得一提的是/, '报告腔「值得一提的是」'],
  [/让我们一起/, '口号腔「让我们一起」'],
  [/希望(这|以上)(些)?(对你|能)(有)?(所)?帮助/, '客服腔'],
]

function hits(text) {
  const out = []
  for (const [re, why] of BLACKLIST) if (re.test(text)) out.push(why)
  return out
}

module.exports = { BLACKLIST, hits }
